const $ = (id) => document.getElementById(id);

const copy = {
  en: { title: 'Vibe IDE Code Setup', product: 'Developer environment', welcomeEyebrow: 'WELCOME', welcomeTitle: 'Set up your coding environment', language: 'Installer language', system: 'Detected system', prepare: 'Setup downloads required tools and prepares your development environment.', emulator: 'Android SDK and an emulator profile are prepared, but the emulator will not start.', time: 'This can take several minutes and requires an internet connection.', start: 'Start setup', progressEyebrow: 'SETUP IN PROGRESS', progress: 'Installation progress', stages: 'Installation stages', technical: 'Technical activity', live: 'LIVE', waiting: 'Waiting for installer activity...', count: (c, t) => `${c} of ${t} steps`, pending: 'Queued', active: 'Working', complete: 'Ready', failed: 'Needs attention', completeState: 'Complete', failureState: 'Action required', welcomeState: 'Ready to begin', checklist: 'Setup complete', open: 'Open Vibe IDE Code', close: 'Close installer', copy: 'Copy details', copied: 'Copied', checklistItems: ['Required development tools are ready', 'OpenCode and Claude Code are available', 'Android emulator was not launched'] },
  es: { title: 'Configuracion de Vibe IDE Code', product: 'Entorno de desarrollo', welcomeEyebrow: 'BIENVENIDO', welcomeTitle: 'Prepara tu entorno de programacion', language: 'Idioma del instalador', system: 'Sistema detectado', prepare: 'La configuracion descarga las herramientas necesarias y prepara tu entorno de desarrollo.', emulator: 'Se preparan Android SDK y un perfil de emulador, pero el emulador no se iniciara.', time: 'Puede tardar varios minutos y requiere conexion a internet.', start: 'Iniciar configuracion', progressEyebrow: 'CONFIGURACION EN CURSO', progress: 'Progreso de instalacion', stages: 'Etapas de instalacion', technical: 'Actividad tecnica', live: 'EN VIVO', waiting: 'Esperando actividad del instalador...', count: (c, t) => `${c} de ${t} pasos`, pending: 'En cola', active: 'En curso', complete: 'Listo', failed: 'Requiere atencion', completeState: 'Completado', failureState: 'Accion necesaria', welcomeState: 'Listo para comenzar', checklist: 'Configuracion completa', open: 'Abrir Vibe IDE Code', close: 'Cerrar instalador', copy: 'Copiar detalles', copied: 'Copiado', checklistItems: ['Las herramientas de desarrollo necesarias estan listas', 'OpenCode y Claude Code estan disponibles', 'El emulador de Android no se inicio'] },
};

function render(status) {
  const t = copy[status.language] || copy.en;
  const welcome = status.status === 'welcome';
  const total = Math.max(0, Number(status.total) || 0);
  const current = Math.min(total, Math.max(0, Number(status.current) || 0));
  const percent = total ? Math.round((Math.min(total, Number(status.progress) || 0) / total) * 100) : 0;
  document.documentElement.lang = status.language || 'en'; document.title = t.title; document.body.className = status.status;
  $('product').textContent = t.product; $('state').textContent = welcome ? t.welcomeState : status.status === 'success' ? t.completeState : status.status === 'failure' ? t.failureState : t.active;
  $('eyebrow').textContent = welcome ? t.welcomeEyebrow : t.progressEyebrow; $('heading').textContent = welcome ? t.welcomeTitle : status.title; $('detail').textContent = welcome ? t.prepare : status.detail;
  $('welcome').hidden = !welcome; $('installation').hidden = welcome; $('actions').hidden = !['success', 'failure'].includes(status.status);
  $('language-label').textContent = t.language; $('language').value = status.language || 'en'; $('system-title').textContent = t.system;
  $('system-summary').textContent = status.system ? `${status.system.platform} · ${status.system.cpu} · ${status.system.memory}` : '';
  $('welcome-points').replaceChildren(...[t.prepare, t.emulator, t.time].map((text) => { const item = document.createElement('li'); item.textContent = text; return item; })); $('start').textContent = t.start;
  $('progress-panel').setAttribute('aria-label', t.progress); $('stages').setAttribute('aria-label', t.stages); $('count').textContent = total ? t.count(current, total) : ''; $('percent').textContent = `${percent}%`; $('bar').style.width = `${percent}%`; $('.track').setAttribute('aria-valuenow', String(percent));
  $('stages').replaceChildren(...(status.stages || []).map((stage, index) => { const item = document.createElement('li'); item.className = `stage ${stage.status}`; const indicator = document.createElement('span'); indicator.className = 'indicator'; indicator.textContent = stage.status === 'complete' ? 'OK' : stage.status === 'failed' ? '!' : stage.status === 'active' ? '...' : String(index + 1); const text = document.createElement('div'); const name = document.createElement('div'); name.className = 'stage-name'; name.textContent = stage.label; const detail = document.createElement('div'); detail.className = 'stage-detail'; detail.textContent = stage.detail; text.append(name, detail); const state = document.createElement('span'); state.className = 'stage-status'; state.textContent = t[stage.status] || stage.status; item.append(indicator, text, state); return item; }));
  $('technical-heading').textContent = t.technical; $('technical-state').textContent = status.status === 'running' ? t.live : ''; $('output').textContent = (status.output || []).join('\n') || t.waiting;
  const success = status.status === 'success'; $('checklist').hidden = !success; $('checklist-title').textContent = t.checklist; $('checklist-items').replaceChildren(...t.checklistItems.map((text) => { const item = document.createElement('li'); item.textContent = text; return item; })); $('open-app').hidden = !success; $('open-app').textContent = t.open; $('acknowledge').textContent = t.close; $('copy-details').hidden = success; $('copy-details').textContent = t.copy;
}

$('start').addEventListener('click', () => window.bootstrap.start($('language').value)); $('acknowledge').addEventListener('click', () => window.bootstrap.acknowledge()); $('open-app').addEventListener('click', () => window.bootstrap.openApp()); $('copy-details').addEventListener('click', async () => { await window.bootstrap.copyDetails(); $('copy-details').textContent = (copy[$('language').value] || copy.en).copied; }); window.bootstrap.onStatus(render); window.bootstrap.getStatus().then(render);
